<section class="container inner-hero"><p class="eyebrow"><?=e($row['body']['eyebrow']??'')?></p><h1><?=e($row['title'])?></h1><p class="large-copy"><?=e($row['summary'])?></p></section><div class="container page-showcase"><?php page_slider($row,'pages','projects');?></div><section class="container section"><nav class="project-filters" aria-label="<?=t('تصفية المشاريع','Filter projects')?>"><a href="<?=url('projects')?>" <?=getstr('sector')===''?'aria-current="true"':''?>><?=t('الكل','All')?></a><?php foreach($sectors as $sector):if(!array_filter($projects,fn($p)=>(int)$p['sector_id']===(int)$sector['id']))continue;?><a href="<?=url('projects?sector='.$sector['slug'])?>" <?=getstr('sector')===$sector['slug']?'aria-current="true"':''?>><?=e($sector['title'])?></a><?php endforeach;?></nav><?php $filter=record('sectors',getstr('sector'));$listedProjects=$filter?array_values(array_filter($projects,fn($p)=>(int)$p['sector_id']===(int)$filter['id'])):$projects;require ROOT.'/app/views/project-grid.php';?></section>
